public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize a queue to keep track of n-tersections to visit
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection
        int[] current = queue.remove();

        // Check if the current n-tersection is the ending n-tersection
        if (Arrays.equals(current, end)) {
            // Return "can be travelled" if the ending n-tersection is reached
            return "can be travelled";
        }

        // Mark the current n-tersection as visited
        visited[current[0] * n + current[1]] = true;

        // Loop through the paths
        for (int[] path : paths) {
            // Check if the current n-tersection is one of the path's endpoints
            if (Arrays.equals(current, path[0]) || Arrays.equals(current, path[1])) {
                // Add the other endpoint of the path to the queue
                queue.add(path[0] == current ? path[1] : path[0]);
            }
        }
    }

    // Return "cannot be travelled" if the ending n-tersection is not reached
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null) {
      return "cannot be travelled";
    }

    boolean[] visited = new boolean[n];
    Deque<int[]> queue = new ArrayDeque<>();
    queue.offer(start);
    visited[start[0] * n + start[1]] = true;

    while (!queue.isEmpty()) {
      int[] current = queue.poll();
      if (current[0] == end[0] && current[1] == end[1]) {
        return "can be travelled";
      }

      for (int[] direction : paths) {
        int newX = current[0] + direction[0];
        int newY = current[1] + direction[1];
        if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX * n + newY]) {
          visited[newX * n + newY] = true;
          queue.offer(new int[]{newX, newY});
        }
      }
    }

    return "cannot be travelled";
  }

