public static double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the trimmed mean
    int startIndex = (int) (arr.length * 0.05);
    int endIndex = arr.length - startIndex - 1;
    double sum = 0;
    for (int i = startIndex; i <= endIndex; i++) {
      sum += arr[i];
    }
    return sum / (arr.length - 2 * startIndex);
  }

public double trimMean(int[] arr) {
    PriorityQueue<Integer> minPq = new PriorityQueue<>();
    PriorityQueue<Integer> maxPq = new PriorityQueue<>(Collections.reverseOrder());

    // Add the smallest 5% and largest 5% of the elements to the priority queues
    int n = arr.length;
    int count = (int) (n * 0.05);
    for (int i = 0; i < count; i++) {
        minPq.add(arr[i]);
        maxPq.add(arr[n - i - 1]);
    }

    // Calculate the mean without the smallest 5% and largest 5% of the elements
    double mean = 0;
    for (int i = count; i < n - count; i++) {
        mean += arr[i];
    }
    mean /= (n - 2 * count);

    // Remove the smallest 5% and largest 5% of the elements from the priority queues
    // and adjust the mean accordingly
    for (int i = count + 1; i < n - count - 1; i++) {
        if (minPq.peek() <= arr[i]) {
            minPq.remove();
            mean -= minPq.peek();
        } else if (arr[i] <= maxPq.peek()) {
            maxPq.remove();
            mean += maxPq.peek();
        }
    }

    // Return the mean with an error within 10^-5
    if (Double.compare(mean, mean + 1E-5) < 0) {
        return mean;
    } else {
        return mean + 1E-5;
    }
}

public double trimMean(int[] arr) {
    double sum = 0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }
    double mean = sum / arr.length;
    double trimmedArr = new ArrayList<>(arr);
    trimmedArr.sort(Comparator.comparingInt(val -> val));
    double min = trimmedArr.stream().skip(arr.length * 0.05).findFirst().get();
    double max = trimmedArr.stream().skip(1 - arr.length * 0.05).findFirst().get();
    sum = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] > min && arr[i] < max) {
            sum += arr[i];
        }
    }
    double trimmedMean = sum / (arr.length - 2);
    return trimmedMean;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the 5% smallest and largest elements
    int minIndex = (int) (arr.length * 0.05);
    int maxIndex = (int) (arr.length * 0.95);

    // Calculate the mean of the remaining elements
    double sum = 0;
    for (int i = minIndex; i <= maxIndex; i++) {
        sum += arr[i];
    }
    double mean = sum / (arr.length - maxIndex + minIndex);

    // Round the mean to 5 decimal places
    mean = Math.round(mean * 100000) / 100000;

    return mean;
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Compute the mean of the top and bottom 5% of the array
    int top5Percentile = (int) (arr.length * 0.05);
    int bottom5Percentile = (int) (arr.length * 0.95);
    double meanTop = 0;
    for (int i = 0; i < top5Percentile; i++) {
        meanTop += arr[i];
    }
    meanTop /= top5Percentile;

    double meanBottom = 0;
    for (int i = arr.length - 1; i >= bottom5Percentile; i--) {
        meanBottom += arr[i];
    }
    meanBottom /= arr.length - bottom5Percentile;

    // Return the mean of the top and bottom 5% of the array
    return (meanTop + meanBottom) / 2;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    Map<Integer, Integer> counts = new HashMap<>();
    for (int num : arr) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
    }
    for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
        int num = entry.getKey();
        int count = entry.getValue();
        if (count > n / 2 || (count > 0 && num % k != 0)) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] sums = new int[k];
    for (int i = 0; i < n; i++) {
        int val = arr[i];
        for (int j = 0; j < k; j++) {
            sums[j] += val % k == 0 ? val / k : 0;
        }
    }
    for (int sum : sums) {
        if (sum != n / 2) {
            return false;
        }
    }
    return true;
}

public static boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 == 1 || k == 1) {
        return false;
    }

    int divisiblePairs = 0;
    for (int i = 0; i < arr.length - 1; i += 2) {
        if (arr[i] % k == 0 && arr[i + 1] % k == 0) {
            divisiblePairs++;
        }
    }

    return divisiblePairs == arr.length / 2;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 1 || arr.length < k) return false;

    // Count the number of elements in each equivalence class mod k
    int[] counts = new int[k];
    for (int i = 0; i < arr.length; i++) {
        int equivalenceClass = arr[i] % k;
        counts[equivalenceClass]++;
    }

    // If at least one equivalence class has more than half the elements, return true
    for (int i = 0; i < k; i++) {
        if (counts[i] > arr.length / 2) return true;
    }

    return false;
}

public boolean canArrange(int[] arr, int k) {
