    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }
    int target = sum / (n / 2);
    if (target % k != 0) {
        return false;
    }
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] + arr[j] == target) {
                return true;
            }
        }
    }
    return false;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a 2D array to store the distance of each node from node 0
    int[][] distances = new int[n][n];
    for (int[] distance : distances) {
        Arrays.fill(distance, -1);
    }
    distances[0][0] = 0;

    // Initialize a queue to store the nodes to be visited
    Queue<Node> queue = new LinkedList<>();
    queue.add(new Node(0, 0));

    // Loop until all nodes are visited
    while (!queue.isEmpty()) {
        Node currentNode = queue.remove();
        int currentDistance = distances[0][currentNode.id];

        // If the current node has an apple, we can return to node 0 after visiting it
        if (hasApple[currentNode.id]) {
            return currentDistance;
        }

        // Iterate over the neighbors of the current node
        for (int neighborId : edges[currentNode.id]) {
            // If the neighbor is not yet visited, add it to the queue and set its distance to the current distance plus 1
            if (distances[0][neighborId] == -1) {
                queue.add(new Node(neighborId, currentDistance + 1));
                distances[0][neighborId] = currentDistance + 1;
            }
        }
    }
    return -1;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Create a graph from the edge list
  Graph graph = new Graph(n, edges);

  // Initialize a priority queue for the nodes to visit
  PriorityQueue<Node> queue = new PriorityQueue<>(Comparator.comparingInt(Node::getValue));

  // Mark the source node as visited and add it to the queue
  graph.nodes[0].visited = true;
  queue.add(graph.nodes[0]);

  // Variables to keep track of the time and the collected apples
  int time = 0;
  int apples = 0;

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Get the node with the highest priority from the queue
    Node current = queue.poll();

    // If the current node has an apple and it hasn't been visited before, collect it and increment the time
    if (current.hasApple && !current.visited) {
      apples++;
      time++;
    }

    // Mark the current node as visited
    current.visited = true;

    // Loop over the current node's neighbors
    for (int neighbor : graph.neighbors[current.index]) {
      // If the neighbor has not been visited, add it to the queue and set its distance to the current node
      if (!graph.nodes[neighbor].visited) {
        queue.add(graph.nodes[neighbor]);
        graph.nodes[neighbor].distance = current.distance + 1;
      }
    }
  }

  // Return the maximum time required to collect all the apples
  return Math.max(apples, time);
}

