public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Create a list to store the ending times for each node
  List<Integer> endingTimes = new ArrayList<Integer>(n);

  // Initialize the ending times for all nodes to -1
  for (int i = 0; i < n; i++) {
    endingTimes.add(-1);
  }

  // Create a queue to store the nodes to visit
  Queue<Integer> queue = new LinkedList<Integer>();

  // Add node 0 to the queue
  queue.add(0);

  // Set the starting time to 0
  int time = 0;

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Get the next node to visit
    int node = queue.remove();

    // If the node has not been visited before, visit it and add its neighbors to the queue
    if (endingTimes.get(node) == -1) {
      // Increment the time if the node has an apple
      if (hasApple[node]) {
        time++;
      }

      // Set the ending time for the node
      endingTimes.set(node, time);

      // Add the neighbors to the queue
      for (int[] edge : edges) {
        if (edge[0] == node) {
          queue.add(edge[1]);
        }
      }
    }
  }

  // Find the maximum ending time
  int maxEndingTime = -1;
  for (int endingTime : endingTimes) {
    if (endingTime > maxEndingTime) {
      maxEndingTime = endingTime;
    }
  }

  // Return the maximum ending time plus the time it takes to return to node 0
  return maxEndingTime + time;
}

