public String sortString(String s) {
    // Initialize an empty string to store the sorted result
    String result = "";

    // Create a map to store the frequency of each character in s
    Map<Character, Integer> freq = new HashMap<>();
    for (char c : s.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }

    // Iterate through s in reverse order until all characters are used
    while (!freq.isEmpty()) {
        // Find the smallest character that has not been used yet
        char smallest = Character.MAX_VALUE;
        for (Map.Entry<Character, Integer> entry : freq.entrySet()) {
            if (entry.getValue() > 0 && entry.getKey() < smallest) {
                smallest = entry.getKey();
            }
        }

        // Append the smallest character to the result
        result += smallest;

        // Reduce the frequency of the smallest character
        freq.put(smallest, freq.get(smallest) - 1);

        // If there are no more instances of the smallest character, remove it from the map
        if (freq.get(smallest) == 0) {
            freq.remove(smallest);
        }

        // Find the largest character that has not been used yet
        char largest = Character.MIN_VALUE;
        for (Map.Entry<Character, Integer> entry : freq.entrySet()) {
            if (entry.getValue() > 0 && entry.getKey() > largest) {
                largest = entry.getKey();
            }
        }

        // Append the largest character to the result
        result += largest;

        // Reduce the frequency of the largest character
        freq.put(largest, freq.get(largest) - 1);

        // If there are no more instances of the largest character, remove it from the map
        if (freq.get(largest) == 0) {
            freq.remove(largest);
        }
    }

    return result;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (!s.isEmpty()) {
        // pick the smallest character
        char smallest = s.charAt(0);
        int smallestIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
                smallestIndex = i;
            }
        }
        result.append(smallest);
        s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);

        // pick the smallest character that is greater than the last appended character
        char nextSmallest = smallest;
        while (result.charAt(result.length() - 1) >= nextSmallest) {
            nextSmallest++;
        }
        result.append(nextSmallest);

        // pick the largest character
        char largest = s.charAt(s.length() - 1);
        int largestIndex = s.length() - 1;
        for (int i = s.length() - 2; i >= 0; i--) {
            if (s.charAt(i) > largest) {
                largest = s.charAt(i);
                largestIndex = i;
            }
        }
        result.append(largest);
        s = s.substring(0, largestIndex) + s.substring(largestIndex + 1);

        // pick the largest character that is smaller than the last appended character
        char nextLargest = largest;
        while (result.charAt(result.length() - 1) <= nextLargest) {
            nextLargest--;
        }
        result.append(nextLargest);
    }
    return result.toString();
}

