public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int halfSum = sum / 2;
    int count = 0;
    for (int num : nums) {
        if (num <= halfSum) {
            count++;
        }
    }
    return count >= 2;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of the array elements
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the array elements
    int average = sum / nums.length;

    // Initialize two variables to keep track of the sum of the left and right arrays
    int leftSum = 0;
    int rightSum = 0;

    // Iterate through the array
    for (int i = 0; i < nums.length; i++) {
        // If the current element is less than the average, add it to the left sum
        if (nums[i] < average) {
            leftSum += nums[i];
        }
        // Otherwise, add it to the right sum
        else {
            rightSum += nums[i];
        }
    }

    // Check if the left sum is equal to the right sum
    return leftSum == rightSum;
}

