    int leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
    }
    int rightSum = sum - leftSum;

    if (leftSum == avg) {
        return true;
    } else if (rightSum == avg) {
        return true;
    } else {
        return false;
    }
}

