    }
    double average = (double) sum / nums.length;

    // Iterate over the array and check if there is a pair with the same average
    for (int i = 0; i < nums.length; i++) {
        int pairSum = nums[i];
        for (int j = i + 1; j < nums.length; j++) {
            pairSum += nums[j];
            if (pairSum == 2 * average) {
                // If a pair with the same average is found, return true
                return true;
            }
        }
    }

    // If no pair with the same average is found, return false
    return false;
}

