public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n+1];
    dp[n-1] = cost[n-1];
    dp[n] = cost[n];

    for (int i = n-1; i >= 0; i--) {
        dp[i] = Math.min(dp[i], dp[i+1]) + cost[i];
    }

    return dp[0];
}

