    Set<String> substrings = new HashSet<>();

    // Loop through the input string and find all substrings of length k
    for (int i = 0; i < s.length() - k + 1; i++) {
        String substring = s.substring(i, i + k);
        substrings.add(substring);
    }

    // Check if all possible substrings of length k are present in the input string
    for (int i = 0; i < (1 << k); i++) {
        String binaryString = String.format("%" + k + "s", i).replace(' ', '0');
        if (!substrings.contains(binaryString)) {
            return false;
        }
    }

