public int minOperations(int n) {
    int minOps = 0;
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    while (minOps < n - 1) {
        int x = -1;
        int y = -1;
        for (int i = 0; i < n; i++) {
            if (arr[i] != arr[0]) {
                x = i;
                for (int j = 0; j < n; j++) {
                    if (arr[j] == arr[0]) {
                        y = j;
                        break;
                    }
                }
            }
        }

        if (x == -1 || y == -1) {
            break;
        }

        arr[x] -= 1;
        arr[y] += 1;
        minOps++;
    }

    return minOps;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int total = 0;
    while (true) {
        int x = -1;
        int y = -1;
        for (int i = 0; i < n; i++) {
            if (arr[i] != 0) {
                x = i;
                break;
            }
        }

        for (int j = 0; j < n; j++) {
            if (arr[j] != 0) {
                y = j;
                break;
            }
        }

        if (x == -1 && y == -1) {
            return total;
        }

        arr[x] -= 1;
        arr[y] += 1;
        total++;
    }
}

public int minOperations(int n) {
  // Calculate the number of operations required to make all elements equal
  // to the middle element in the array
  int mid = n / 2;
  int operations = 0;
  for (int i = 0; i < n; i++) {
    if (i < mid) {
      operations += (mid - i);
    } else {
      operations += (i - mid);
    }
  }
  return operations;
}

public int minOperations(int n) {
  int operations = 0;
  for (int i = 0; i < n; i++) {
    int x = 2 * i + 1;
    int y = 2 * (n - 1 - i) + 1;
    int diff = Math.abs(x - y);
    operations += diff;
  }
  return operations;
}

