    for (int i = 0; i < nums.length; i++) {
        int sum = 0;
        for (int j = i; j < nums.length; j++) {
            sum += Math.abs(nums[j]);
            if (sum > maxSum) {
                maxSum = sum;
            }
        }
    }
    return maxSum;
}

public static int maxAbsoluteSum(int[] nums) {
    int n = nums.length;
    Set<Integer> seen = new HashSet<>();
    int maxSum = 0;
    for (int i = 0; i < n; i++) {
        int sum = nums[i];
        for (int j = i + 1; j < n; j++) {
            sum += nums[j];
            if (seen.contains(sum)) {
                maxSum = Math.max(maxSum, sum);
                break;
            }
            seen.add(sum);
        }
    }
    return maxSum;
}

