    int maxSum = 0, currentSum = 0;

    // Loop through the array
    for (int num : nums) {
        // Update the current sum
        currentSum += num;

        // Update the maximum absolute sum
        maxSum = Math.max(maxSum, Math.max(currentSum, -currentSum));
    }

    return maxSum;
}

