    String currentDirectory = "/";

    // Initialize the number of operations to 0
    int numOperations = 0;

    // Iterate over the logs
    for (String log : logs) {
        // Remove the leading "./" or "../" if present
        if (log.startsWith("./") || log.startsWith("../")) {
            log = log.substring(2);
        }

        // If the log is a directory name, create it
        // If the log is "..", move up one level in the directory tree
        // If the log is ".", move to the main folder
        if (log.endsWith("/")) {
            // Create the directory
            currentDirectory = currentDirectory + log;
        } else if (log.equals("..")) {
            // Move up one level in the directory tree
            int index = currentDirectory.lastIndexOf("/");
            currentDirectory = currentDirectory.substring(0, index);
        } else if (log.equals(".")) {
            // Move to the main folder
            currentDirectory = "/";
        }

        // Increment the number of operations
        numOperations++;
    }

    // Return the number of operations
    return numOperations;
}

