public static int largestRectangleArea(int[] heights) {
    // Calculate the stack of intervals that can be formed by the bars
    Stack<Pair<Integer, Integer>> stack = new Stack<>();
    int n = heights.length;
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        while (!stack.empty() && stack.peek().second < heights[i]) {
            Pair<Integer, Integer> top = stack.pop();
            int width = (i - stack.peek().first - 1);
            maxArea = Math.max(maxArea, top.second * width);
        }
        stack.push(new Pair(i, heights[i]));
    }

    // Process remaining intervals
    while (!stack.empty()) {
        Pair<Integer, Integer> top = stack.pop();
        int width = (n - stack.peek().first - 1);
        maxArea = Math.max(maxArea, top.second * width);
    }

    return maxArea;
}

