public static int findSmallestInteger(int n) {

    // Initialize the output variable
    int smallestInteger = -1;

    // Convert the input integer to a string
    String inputString = String.valueOf(n);

    // Length of the input string
    int len = inputString.length();

    // Array to store the digits of the input string
    int[] digits = new int[len];

    // Parse the input string and store the digits in the digits array
    for (int i = 0; i < len; i++) {
        digits[i] = inputString.charAt(i) - '0';
    }

    // Sort the digits array in ascending order
    Arrays.sort(digits);

    // Iterate over the digits array and check if the current digit is less than the previous digit
    // If the current digit is less than the previous digit, then it is not possible to form the smallest integer
    // If the current digit is greater than or equal to the previous digit, then it is possible to form the smallest integer
    // If all the digits are greater than or equal to each other, then it is not possible to form the smallest integer
    for (int i = 0; i < len - 1; i++) {
        if (digits[i] < digits[i + 1]) {
            return -1;
        }
    }

    // Form the smallest integer by converting the sorted digits array back to a string
    String smallestIntegerStr = Arrays.toString(digits).replaceAll("\\[|\\]|,", "");

    // Convert the smallest integer string to an integer
    smallestInteger = Integer.parseInt(smallestIntegerStr);

    // Return the smallest integer
    return smallestInteger;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to a string
    String numStr = Integer.toString(n);

    // Sort the digits in ascending order
    char[] sortedDigits = numStr.toCharArray();
    Arrays.sort(sortedDigits);

    // Reverse the sorted digits to form the rearranged integer
    StringBuilder rearrangedStr = new StringBuilder();
    for (char digit : sortedDigits) {
        rearrangedStr.append(digit);
    }

    // Convert the rearranged integer string to an integer
    int rearrangedInt = Integer.parseInt(rearrangedStr.toString());

    // Check if the rearranged integer is greater than the given integer
    if (rearrangedInt > n) {
        return rearrangedInt;
    }

    // If the rearranged integer is not greater than the given integer, return -1
    return -1;
}

