public static boolean isBoomerang(int[][] points) {
    int n = points.length;
    if (n < 3) {
        return false;
    }

    // Check if any two points are identical
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (points[i][0] == points[j][0] &&
                points[i][1] == points[j][1]) {
                return false;
            }
        }
    }

    // Check if the three points are collinear
    int a = (points[1][1] - points[0][1]) * (points[2][0] - points[0][0]);
    int b = (points[2][1] - points[0][1]) * (points[1][0] - points[0][0]);
    if (a == b) {
        return false;
    }

    // Check if the area of the triangle formed by the three points is negative
    int c = (points[1][1] - points[0][1]) * (points[2][0] - points[1][0]);
    if (c < 0) {
        return false;
    }

    return true;
}

public static boolean isBoomerang(int[][] points) {
    int n = points.length;

    // treat the case where the line has 3 or fewer points
    if (n < 3) {
        return false;
    }

    // compute the slope and y-intercept of the line
    double slope = (double)(points[0][1] - points[1][1]) / (points[0][0] - points[1][0]);
    double intercept = points[1][1] - slope * points[1][0];

    // check if the slope and y-intercept satisfy the conditions of a boomerang
    for (int i = 0; i < n; i++) {
        double x = points[i][0];
        double y = slope * x + intercept;
        if (y != x) {
            return false;
        }
    }

    return true;
}

