public static int findNthUglyNumber(int n) {
  int[] dp = new int[n + 1];
  dp[1] = 1;
  int i2 = 1, i3 = 1, i5 = 1;
  for (int i = 2; i <= n; i++) {
    int next = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
    if (next == dp[i2] * 2) i2++;
    if (next == dp[i3] * 3) i3++;
    if (next == dp[i5] * 5) i5++;
    dp[i] = next;
  }
  return dp[n];
}

public static int findNthUglyNumber(int n) {
    if (n == 1) {
        return 1;
    }

    int[] factors = {2, 3, 5};
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;
    for (int i = 1; i < n; i++) {
        int minMultiplier = Math.min(factors[index2] * factors[index3] * factors[index5],
                                     factors[index2] * factors[index3] * factors[index5] + 1);
        uglyNumbers[i] = minMultiplier;

        if (minMultiplier == factors[index2] * factors[index3] * factors[index5]) {
            index2++;
        }
        if (minMultiplier == factors[index2] * factors[index3] * factors[index5] + 1) {
            index3++;
        }
        if (minMultiplier == factors[index2] * factors[index3] * factors[index5] + 2) {
            index5++;
        }
    }

    return uglyNumbers[n - 1];
}

