        dp[i] = min;
    }
    return dp[n];
}

public static int findNthUglyNumber(int n) {
    if (n < 1) throw new IllegalArgumentException("n must be greater than 0");

    // Initialize a queue to store the ugly numbers
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(1);

    // Initialize the variables to keep track of the factors
    int factor2 = 0, factor3 = 0, factor5 = 0;

    // Loop until the queue has the desired size
    while (queue.size() < n) {
        // Calculate the next ugly number
        int next = Math.min(factor2 * 2, Math.min(factor3 * 3, factor5 * 5));

        // Add the next ugly number to the queue
        queue.offer(next);

        // Update the factors
        if (next == factor2 * 2) factor2++;
        if (next == factor3 * 3) factor3++;
        if (next == factor5 * 5) factor5++;
    }

    // Return the nth ugly number
    return queue.poll();
}

public static int findNthUglyNumber(int n) {
    if (n < 1) {
        return -1;
    }

    int[] primes = {2, 3, 5};
    int[] powers = {0, 0, 0};
    int[] results = new int[n];

    results[0] = 1;
    for (int i = 1; i < n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 0; j < 3; j++) {
            int prime = primes[j];
            int power = powers[j];
            int result = prime * (int) Math.pow(prime, power);
            if (result < min) {
                min = result;
                results[i] = result;
                powers[j]++;
            }
        }
    }
    return results[n-1];
}

